<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Kanban Board</title>
<style>
  :root {
    --bg: #0f1420;
    --panel: #171d2b;
    --panel-2: #1e2637;
    --card: #232c40;
    --card-hover: #2a3450;
    --text: #e8ecf5;
    --muted: #93a0bb;
    --line: #2c3purple;
    --border: #2c364d;
    --accent: #5b8cff;
    --todo: #6f8cff;
    --doing: #f0b429;
    --done: #35c48a;
    --danger: #ff6b6b;
    --radius: 14px;
  }

  * { box-sizing: border-box; }

  html, body { height: 100%; }

  body {
    margin: 0;
    background:
      radial-gradient(1100px 600px at 12% -10%, #1c2740 0%, transparent 60%),
      radial-gradient(900px 500px at 100% 0%, #1b2a3c 0%, transparent 55%),
      var(--bg);
    color: var(--text);
    font: 15px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    -webkit-font-smoothing: antialiased;
    min-height: 100vh;
  }

  .wrap {
    max-width: 1180px;
    margin: 0 auto;
    padding: 36px 24px 64px;
  }

  header.top {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 16px;
    margin-bottom: 28px;
  }

  h1 {
    margin: 0;
    font-size: 25px;
    letter-spacing: -0.02em;
    font-weight: 650;
  }

  h1 span {
    color: var(--muted);
    font-weight: 400;
    font-size: 14px;
    display: block;
    letter-spacing: 0;
    margin-top: 4px;
  }

  .composer {
    display: flex;
    gap: 10px;
    margin-left: auto;
  }

  #new-card {
    width: 300px;
    max-width: 60vw;
    padding: 11px 14px;
    border-radius: 10px;
    border: 1px solid var(--border);
    background: var(--panel-2);
    color: var(--text);
    font: inherit;
    outline: none;
    transition: border-color .15s, box-shadow .15s;
  }
  #new-card::placeholder { color: #6f7d99; }
  #new-card:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(91,140,255,.18);
  }

  #add-card {
    padding: 11px 20px;
    border-radius: 10px;
    border: 1px solid transparent;
    background: linear-gradient(180deg, #6b98ff, #4a7cf0);
    color: #fff;
    font: inherit;
    font-weight: 600;
    cursor: pointer;
    transition: transform .08s, filter .15s;
    box-shadow: 0 6px 18px -8px rgba(74,124,240,.9);
  }
  #add-card:hover { filter: brightness(1.08); }
  #add-card:active { transform: translateY(1px); }

  .board {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 18px;
    align-items: start;
  }

  .column {
    background: linear-gradient(180deg, rgba(255,255,255,.03), rgba(255,255,255,0)) , var(--panel);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 14px 14px 16px;
    min-height: 240px;
    display: flex;
    flex-direction: column;
    transition: background .15s, border-color .15s, box-shadow .15s;
  }

  .column.drag-over {
    border-color: var(--accent);
    background: var(--panel-2);
    box-shadow: 0 0 0 3px rgba(91,140,255,.14) inset;
  }

  .col-header {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 2px 4px 14px;
  }

  .dot {
    width: 9px;
    height: 9px;
    border-radius: 50%;
    flex: none;
  }
  #col-todo  .dot { background: var(--todo); }
  #col-doing .dot { background: var(--doing); }
  #col-done  .dot { background: var(--done); }

  .col-title {
    font-size: 13px;
    font-weight: 650;
    letter-spacing: .08em;
    text-transform: uppercase;
    color: #c3cde3;
  }

  .count {
    margin-left: auto;
    min-width: 24px;
    text-align: center;
    font-size: 12px;
    font-weight: 650;
    font-variant-numeric: tabular-nums;
    color: var(--muted);
    background: rgba(255,255,255,.06);
    border: 1px solid var(--border);
    border-radius: 999px;
    padding: 2px 8px;
  }

  .cards {
    display: flex;
    flex-direction: column;
    gap: 10px;
    flex: 1;
    min-height: 90px;
  }

  .card {
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: 10px;
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 11px;
    padding: 12px 12px 12px 14px;
    cursor: grab;
    box-shadow: 0 1px 0 rgba(255,255,255,.04) inset, 0 8px 16px -14px rgba(0,0,0,.9);
    transition: background .15s, transform .08s, border-color .15s, opacity .15s;
    word-break: break-word;
  }
  .card:hover {
    background: var(--card-hover);
    border-color: #3a4870;
  }
  .card:active { cursor: grabbing; }
  .card.dragging { opacity: .4; }

  .card::before {
    content: "";
    position: absolute;
    left: 0; top: 10px; bottom: 10px;
    width: 3px;
    border-radius: 0 3px 3px 0;
    background: var(--accent);
    opacity: .85;
  }
  #col-todo  .card::before { background: var(--todo); }
  #col-doing .card::before { background: var(--doing); }
  #col-done  .card::before { background: var(--done); }

  .card-title {
    flex: 1;
    min-width: 0;
    font-size: 14.5px;
    line-height: 1.45;
  }

  .card-del {
    flex: none;
    width: 24px;
    height: 24px;
    border-radius: 7px;
    border: 1px solid transparent;
    background: transparent;
    color: var(--muted);
    font-size: 15px;
    line-height: 1;
    cursor: pointer;
    opacity: .55;
    transition: all .15s;
  }
  .card:hover .card-del { opacity: 1; }
  .card-del:hover {
    background: rgba(255,107,107,.14);
    border-color: rgba(255,107,107,.35);
    color: var(--danger);
  }

  .empty {
    color: #63719033;
    border: 1px dashed var(--border);
    border-radius: 11px;
    padding: 16px 12px;
    text-align: center;
    font-size: 13px;
    color: #66738f;
  }

  @media (max-width: 780px) {
    .board { grid-template-columns: 1fr; }
    .composer { margin-left: 0; width: 100%; }
    #new-card { flex: 1; max-width: none; width: auto; }
  }
</style>
</head>
<body>
<div class="wrap">
  <header class="top">
    <h1>Kanban Board<span>Drag cards between columns — saved automatically</span></h1>
    <div class="composer">
      <input id="new-card" type="text" placeholder="What needs doing?" autocomplete="off">
      <button id="add-card" type="button">Add card</button>
    </div>
  </header>

  <main class="board">
    <section class="column" id="col-todo" data-col="todo">
      <div class="col-header">
        <span class="dot"></span>
        <span class="col-title">To Do</span>
        <span class="count">0</span>
      </div>
      <div class="cards"></div>
    </section>

    <section class="column" id="col-doing" data-col="doing">
      <div class="col-header">
        <span class="dot"></span>
        <span class="col-title">Doing</span>
        <span class="count">0</span>
      </div>
      <div class="cards"></div>
    </section>

    <section class="column" id="col-done" data-col="done">
      <div class="col-header">
        <span class="dot"></span>
        <span class="col-title">Done</span>
        <span class="count">0</span>
      </div>
      <div class="cards"></div>
    </section>
  </main>
</div>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "kanban.board.v1";
  var COLS = ["todo", "doing", "done"];

  var input   = document.getElementById("new-card");
  var addBtn  = document.getElementById("add-card");
  var columns = {
    todo:  document.getElementById("col-todo"),
    doing: document.getElementById("col-doing"),
    done:  document.getElementById("col-done")
  };

  var seq = 0;

  function containerOf(col) { return columns[col].querySelector(".cards"); }

  /* ---------- persistence ---------- */

  function save() {
    var state = [];
    COLS.forEach(function (col) {
      containerOf(col).querySelectorAll(".card").forEach(function (card) {
        state.push({ id: card.dataset.id, title: card.dataset.title, col: col });
      });
    });
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (e) { /* storage unavailable — board still works in-session */ }
  }

  function load() {
    var raw = null;
    try { raw = localStorage.getItem(STORAGE_KEY); } catch (e) { return []; }
    if (!raw) return [];
    try {
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(function (item) {
        return item && typeof item.title === "string" && COLS.indexOf(item.col) !== -1;
      });
    } catch (e) { return []; }
  }

  /* ---------- rendering ---------- */

  function updateCounts() {
    COLS.forEach(function (col) {
      var n = containerOf(col).querySelectorAll(".card").length;
      columns[col].querySelector(".count").textContent = String(n);
      var box = containerOf(col);
      var placeholder = box.querySelector(".empty");
      if (n === 0 && !placeholder) {
        var p = document.createElement("div");
        p.className = "empty";
        p.textContent = "Drop cards here";
        box.appendChild(p);
      } else if (n > 0 && placeholder) {
        placeholder.remove();
      }
    });
  }

  function nextId() {
    seq += 1;
    return "c" + seq + "-" + Math.floor(Math.random() * 1e6).toString(36);
  }

  function makeCard(title, id) {
    var card = document.createElement("div");
    card.className = "card";
    card.draggable = true;
    card.dataset.id = id || nextId();
    card.dataset.title = title;

    var span = document.createElement("span");
    span.className = "card-title";
    span.textContent = title;

    var del = document.createElement("button");
    del.className = "card-del";
    del.type = "button";
    del.title = "Delete card";
    del.setAttribute("aria-label", "Delete card");
    del.textContent = "\u00D7";
    del.addEventListener("click", function (e) {
      e.stopPropagation();
      card.remove();
      updateCounts();
      save();
    });

    card.addEventListener("dragstart", function (e) {
      card.classList.add("dragging");
      if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = "move";
        try { e.dataTransfer.setData("text/plain", card.dataset.id); } catch (err) {}
      }
      dragged = card;
    });

    card.addEventListener("dragend", function () {
      card.classList.remove("dragging");
      dragged = null;
      COLS.forEach(function (c) { columns[c].classList.remove("drag-over"); });
    });

    return card;
  }

  function addCard(title, col, id) {
    var target = COLS.indexOf(col) !== -1 ? col : "todo";
    var card = makeCard(title, id);
    containerOf(target).appendChild(card);
    return card;
  }

  /* ---------- drag and drop ---------- */

  var dragged = null;

  function cardFromEvent(e) {
    if (dragged) return dragged;
    var id = "";
    try { id = e.dataTransfer ? e.dataTransfer.getData("text/plain") : ""; } catch (err) {}
    if (!id) return null;
    return document.querySelector('.card[data-id="' + id.replace(/"/g, '\\"') + '"]');
  }

  COLS.forEach(function (col) {
    var el = columns[col];

    el.addEventListener("dragover", function (e) {
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = "move";
      el.classList.add("drag-over");
    });

    el.addEventListener("dragenter", function (e) {
      e.preventDefault();
      el.classList.add("drag-over");
    });

    el.addEventListener("dragleave", function (e) {
      if (!el.contains(e.relatedTarget)) el.classList.remove("drag-over");
    });

    el.addEventListener("drop", function (e) {
      e.preventDefault();
      el.classList.remove("drag-over");
      var card = cardFromEvent(e);
      if (!card) return;
      card.classList.remove("dragging");

      var box = containerOf(col);
      var after = null;
      var siblings = Array.prototype.slice.call(box.querySelectorAll(".card"))
        .filter(function (c) { return c !== card; });
      for (var i = 0; i < siblings.length; i++) {
        var r = siblings[i].getBoundingClientRect();
        if (e.clientY < r.top + r.height / 2) { after = siblings[i]; break; }
      }
      if (after) box.insertBefore(card, after);
      else box.appendChild(card);

      dragged = null;
      updateCounts();
      save();
    });
  });

  /* ---------- adding ---------- */

  function submit() {
    var title = input.value.trim();
    if (!title) { input.value = ""; input.focus(); return; }
    addCard(title, "todo");
    input.value = "";
    input.focus();
    updateCounts();
    save();
  }

  addBtn.addEventListener("click", submit);
  input.addEventListener("keydown", function (e) {
    if (e.key === "Enter") { e.preventDefault(); submit(); }
  });

  /* ---------- boot ---------- */

  load().forEach(function (item) { addCard(item.title, item.col, item.id); });
  updateCounts();
})();
</script>
</body>
</html>
